def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/environment/input/water-body-testing-2013.csv'
    return pd.read_csv(path)

def process(waterBodyTesting2012, waterBodyTesting2013) -> pd.DataFrame:
    import pandas as pd

    def prep(df: pd.DataFrame) -> pd.DataFrame:
        d = df.copy()
        d.columns = [c.strip() for c in d.columns]
        # Identify beach column
        beach_col = None
        for c in d.columns:
            if c.lower() in {'beach', 'beach_name', 'site', 'sampling_location', 'location', 'waterbody', 'water_body', 'station'}:
                beach_col = c
                break
        if beach_col is None:
            # fall back to first column
            beach_col = d.columns[0]

        # Identify exceedance indicator column
        exc_col = None
        for c in d.columns:
            cl = c.lower()
            if 'exceed' in cl and ('rate' not in cl):
                exc_col = c
                break
        # Identify measure/value column if indicator not found
        value_col = None
        for c in d.columns:
            cl = c.lower()
            if any(k in cl for k in ['ecoli', 'e. coli', 'enterococci', 'bacteria']) and any(k in cl for k in ['result', 'value', 'count', 'cfu', 'mpn', 'reading']):
                value_col = c
                break

        # Convert exceedance to boolean if present
        if exc_col is not None:
            exc = d[exc_col]
            if exc.dtype == bool:
                d['_exceed'] = exc
            else:
                s = exc.astype(str).str.strip().str.lower()
                d['_exceed'] = s.isin(['1', 'true', 't', 'yes', 'y', 'exceed', 'exceeded', 'exceedance'])
        elif value_col is not None:
            # If only value present, try to infer exceedance using a threshold column if exists
            thresh_col = None
            for c in d.columns:
                cl = c.lower()
                if any(k in cl for k in ['standard', 'threshold', 'limit', 'criteria']) and ('unit' not in cl):
                    thresh_col = c
                    break
            if thresh_col is not None:
                d['_exceed'] = pd.to_numeric(d[value_col], errors='coerce') > pd.to_numeric(d[thresh_col], errors='coerce')
            else:
                # cannot infer; mark as NaN
                d['_exceed'] = pd.NA
        else:
            d['_exceed'] = pd.NA

        out = pd.DataFrame({
            'beach': d[beach_col].astype(str).str.strip(),
            'exceed': d['_exceed']
        })
        # Keep only rows where beach is non-empty
        out = out[out['beach'].notna() & (out['beach'] != '')]
        return out

    d12 = prep(waterBodyTesting2012)
    d13 = prep(waterBodyTesting2013)

    # Aggregate exceedance rate per beach per year
    def agg(d: pd.DataFrame, year: int) -> pd.DataFrame:
        g = d.dropna(subset=['exceed']).groupby('beach').agg(
            samples=('exceed', 'size'),
            exceedances=('exceed', 'sum')
        ).reset_index()
        g[f'rate{year}'] = g['exceedances'] / g['samples']
        g = g[['beach', 'samples', f'rate{year}']].rename(columns={'samples': f'samples{year}'})
        return g

    a12 = agg(d12, 2012)
    a13 = agg(d13, 2013)

    merged = a12.merge(a13, on='beach', how='inner')
    # Exclude beaches with no samples in 2012 (already ensured by inner join, and samples2012>0)
    merged = merged[merged['samples2012'] > 0]
    count_higher = int((merged['rate2013'] > merged['rate2012']).sum())

    return pd.DataFrame([{'higherCount': count_higher}])
